#pragma once
#include "PluginProcessor.h"
class ModSlider : public juce::Slider,public juce::DragAndDropTarget {
    struct Amount final:juce::Component{
        juce::Label title;juce::Slider amount;std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment> binding;
        Amount(SpaceInfinityProcessor& p,const juce::String& id,const juce::String& text){setSize(270,95);title.setText(text,juce::dontSendNotification);title.setBounds(8,6,254,28);amount.setBounds(10,40,250,35);amount.setTextBoxStyle(juce::Slider::TextBoxRight,false,75,25);amount.setSliderStyle(juce::Slider::LinearHorizontal);binding=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.state,id,amount);amount.setMouseDragSensitivity(300);amount.textFromValueFunction=[](double v){return juce::String(v*100,1)+" %";};amount.valueFromTextFunction=[](const juce::String& t){return t.getDoubleValue()/100;};amount.updateText();addAndMakeVisible(title);addAndMakeVisible(amount);}
    };
    SpaceInfinityProcessor* processor=nullptr;juce::String id;int target=-1;std::unique_ptr<Amount> amount;std::unique_ptr<juce::CallOutBox> popup;
public:
    void initialiseModulation(SpaceInfinityProcessor& p,const juce::String& parameter){processor=&p;id=parameter;target=p.flexibleTargetIndex(id);getProperties().set("modParam",id);}
    bool isInterestedInDragSource(const SourceDetails& source)override{return processor&&target>=0&&(source.description.toString().startsWith("INFINITY:LFO:")||source.description.toString().startsWith("INFINITY:MACRO:")||source.description.toString().startsWith("INFINITY:PERFORMANCE:"));}
    void itemDropped(const SourceDetails& source)override{if(processor&&processor->dropModulation(source.description.toString(),id))showAmount(processor->modulationDepthFor(source.description.toString(),id),source.description.toString().replace("INFINITY:","")+" -> "+id);}
    void showAmount(const juce::String& depth,const juce::String& text){if(!processor||depth.isEmpty())return;popup.reset();amount.reset();amount=std::make_unique<Amount>(*processor,depth,text);popup=std::make_unique<juce::CallOutBox>(*amount,getScreenBounds(),nullptr);popup->setLookAndFeel(&getLookAndFeel());popup->enterModalState(true,nullptr,false);}
    void mouseDown(const juce::MouseEvent& e)override{if(!processor||!e.mods.isPopupMenu()){juce::Slider::mouseDown(e);return;}juce::PopupMenu menu;std::vector<std::pair<int,int>> routes;for(int source=0;source<6;++source)for(int slot=0;slot<(source<3?3:16);++slot)if(processor->flexibleSourceTarget(source,slot)==target){const auto title=juce::String(source<3?"Macro ":"LFO ")+juce::String(source<3?source+4:source-2);const int index=int(routes.size());routes.push_back({source,slot});menu.addItem(100+index,title+" amount...");menu.addItem(1000+index,"Remove "+title);}if(routes.empty())menu.addItem(1,"Drag an LFO or blank macro here",false);juce::Component::SafePointer<ModSlider> safe(this);menu.showMenuAsync(juce::PopupMenu::Options{}.withTargetComponent(this),[safe,routes](int action){if(!safe||action<100)return;const bool remove=action>=1000;const int index=action-(remove?1000:100);if(index<0||index>=int(routes.size()))return;const auto [source,slot]=routes[size_t(index)];if(remove)safe->processor->assignFlexibleSource(source,slot,-1);else safe->showAmount(juce::String(source<3?"freeMacroDepth":"lfoFlexDepth")+juce::String(source<3?source:source-3)+"_"+juce::String(slot),"Modulation amount -> "+safe->id);safe->repaint();});}
    void paint(juce::Graphics& g)override{if(processor&&target>=0){bool found=false;for(int source=0;source<6&&!found;++source)for(int slot=0;slot<(source<3?3:16);++slot)if(processor->flexibleSourceTarget(source,slot)==target){const auto key=juce::String(source<3?"freeMacroDepth":"lfoFlexDepth")+juce::String(source<3?source:source-3)+"_"+juce::String(slot);getProperties().set("modDepth",double(processor->state.getRawParameterValue(key)->load()));getProperties().set("modColour",juce::int64(source<3?0xffdfb57c:0xffa6a2ff));found=true;break;}if(!found)getProperties().remove("modDepth");}juce::Slider::paint(g);}
    ~ModSlider()override{popup.reset();amount.reset();}
};
class ModSourceButton:public juce::TextButton {
public:
    juce::String description;
    void mouseDrag(const juce::MouseEvent& e)override{if(e.getDistanceFromDragStart()>5)if(auto* container=juce::DragAndDropContainer::findParentDragContainerFor(this))container->startDragging(description,this);}
};
inline void configureTimeKnob(juce::Slider& slider){auto range=juce::NormalisableRange<double>(slider.getMinimum(),slider.getMaximum(),.00001);range.setSkewForCentre(juce::jlimit(range.start+.00001,range.end-.00001,.025));slider.setNormalisableRange(range);slider.setMouseDragSensitivity(350);slider.textFromValueFunction=[](double v){return v<.1?juce::String(v*1000,2)+" ms":juce::String(v,3)+" s";};slider.valueFromTextFunction=[](const juce::String& s){return s.getDoubleValue()/(s.containsIgnoreCase("ms")?1000:1);};slider.setTooltip("Fine timing near zero. Shift-drag for precision; type ms or seconds; double-click resets.");slider.updateText();}
